document.addEventListener("DOMContentLoaded",function(){const e=document.getElementById("podcast-growth-form");e&&e.addEventListener("submit",function(e){e.preventDefault();const n=parseFloat(document.getElementById("currentListeners").value),t=parseInt(document.getElementById("monthsActive").value),o=parseInt(document.getElementById("episodesPublished").value),i=document.getElementById("publishingFrequency").value,r=document.getElementById("contentQuality").value,d=document.getElementById("episodeLength").value,a=parseFloat(document.getElementById("marketingBudget").value)||0,s=document.getElementById("socialMediaEffort").value,l=document.getElementById("hostExperience").value,c=document.getElementById("nicheCompetition").value,m=parseInt(document.getElementById("projectionMonths").value);const u={daily:1.4,frequent:1.25,weekly:1,biweekly:.85,monthly:.6},g={basic:.8,good:1,professional:1.3,exceptional:1.6};let h=1;a>0&&(h=1+Math.min(a/500*.3,.5));const p={minimal:.9,moderate:1,active:1.2,intensive:1.4},v={new:.8,some:1,experienced:1.3,influencer:1.8},b={low:1.3,medium:1,high:.75,extreme:.6},y=u[i]*g[r]*{short:.9,medium:1,long:1.1,extended:.95}[d]*h*p[s]*v[l]*b[c],f=Math.min(1.15*y,1.5),$=f*Math.max(.7,1-t/100);let x=n;const w=[];for(let e=1;e<=m;e++)x*=$,w.push({month:e,listeners:Math.round(x)});const M=x,E=(M-n)/n*100,I=(Math.max(t,1),1.3*M),B=M>1e3?M/1e3*25:0,F=.02*M,S=M>500?.05*M:0,L=B+F+S;let k="",P="";M<1e3?(k="🌱 Foundation Building Phase",P="warning"):M<5e3?(k="📈 Growth Phase",P="info"):M<25e3?(k="🚀 Scaling Phase",P="success"):(k="⭐ Established Show",P="success");document.getElementById("podcast-growth-result").innerHTML=`\n      <h3>🎙️ Your Podcast Growth Projection</h3>\n      \n      <div class="insight-cards">\n        <div class="insight-card info">\n          <h6>👥 Current Status</h6>\n          <div class="big-number">${n.toLocaleString()}</div>\n          <p>Monthly listeners<br>\n          ${o} episodes published<br>\n          Active for ${t} months</p>\n        </div>\n        \n        <div class="insight-card ${P}">\n          <h6>📊 Projected Growth (${m}M)</h6>\n          <div class="big-number">${Math.round(M).toLocaleString()}</div>\n          <p>Monthly listeners<br>\n          ${E>0?"+":""}${Math.round(E)}% total growth<br>\n          ${k}</p>\n        </div>\n        \n        <div class="insight-card success">\n          <h6>💰 Revenue Potential</h6>\n          <div class="big-number">$${Math.round(L).toLocaleString()}</div>\n          <p>Monthly revenue estimate<br>\n          Sponsors: $${Math.round(B).toLocaleString()}<br>\n          Products/Affiliate: $${Math.round(F+S).toLocaleString()}</p>\n        </div>\n      </div>\n\n      <div style="margin-top: 2rem; padding: 1.5rem; background: #f8f9fa; border-radius: 12px;">\n        <h4>📈 Growth Strategy Analysis</h4>\n        \n        <div style="display: grid; grid-template-columns: 1fr 1fr; gap: 1.5rem; margin-top: 1rem;">\n          <div>\n            <strong>🎯 Strategy Factors:</strong><br>\n            Publishing: ${i} (${(100*u[i]).toFixed(0)}%)<br>\n            Content quality: ${r} (${(100*g[r]).toFixed(0)}%)<br>\n            Marketing budget: $${a}/month (${(100*h).toFixed(0)}%)<br>\n            Social media: ${s} (${(100*p[s]).toFixed(0)}%)<br>\n            Host experience: ${l} (${(100*v[l]).toFixed(0)}%)<br>\n            Competition: ${c} (${(100*b[c]).toFixed(0)}%)\n          </div>\n          \n          <div>\n            <strong>📊 Growth Metrics:</strong><br>\n            Base growth rate: ${(100*(1.15-1)).toFixed(1)}%/month<br>\n            Strategy multiplier: ${y.toFixed(2)}x<br>\n            Adjusted growth: ${(100*($-1)).toFixed(1)}%/month<br>\n            Downloads/episode: ${Math.round(I).toLocaleString()}<br>\n            Monetization ready: ${M>=1e3?"Yes":"In "+Math.ceil((1e3-M)/(M-n)*m)+" months"}\n          </div>\n        </div>\n        \n        <div style="margin-top: 1.5rem; padding: 1rem; background: white; border-radius: 8px;">\n          <strong>📅 Monthly Growth Timeline:</strong><br>\n          <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(100px, 1fr)); gap: 0.5rem; margin-top: 0.5rem; font-size: 0.9em;">\n            ${w.slice(0,12).map(e=>`\n              <div style="text-align: center; padding: 0.5rem; background: #f8f9fa; border-radius: 4px;">\n                M${e.month}<br>\n                <strong>${e.listeners.toLocaleString()}</strong>\n              </div>\n            `).join("")}\n          </div>\n        </div>\n        \n        <div style="margin-top: 1rem; padding: 1rem; background: ${M>=5e3?"#d4edda":M>=1e3?"#fff3cd":"#f8d7da"}; border-radius: 8px; border-left: 4px solid ${M>=5e3?"#28a745":M>=1e3?"#ffc107":"#dc3545"};">\n          <strong>💡 Growth Recommendations:</strong><br>\n          ${M>=5e3?"🎉 Excellent growth trajectory! Focus on monetization, premium content, and community building. Consider expanding to multiple shows or formats.":M>=1e3?"✅ Good growth potential! Continue consistency, improve content quality, and start exploring sponsorship opportunities. Build email list and social following.":"📈 Building foundation. Focus on consistency, audience engagement, and content quality. Increase marketing efforts and consider collaboration opportunities."}<br><br>\n          \n          <strong>🚀 Next Steps:</strong> ${f<1.1?"Increase publishing frequency, improve content quality, or boost marketing efforts to accelerate growth.":"Maintain current strategy while focusing on audience retention and engagement quality."}\n        </div>\n      </div>\n    `})});